css:
.mz *,.mz *::before,.mz *::after{box-sizing: border-box; margin: 0; padding: 0;}
.mz .recuerda{border: 2px solid var(--bosque); border-radius: 10px; padding: 6px 12px; margin-bottom: 8px;}
.mz .recuerda-titulo{font-size: 12.5px; font-weight: 700; margin-bottom: 3px; display: flex; align-items: center; gap: 6px;}
.mz .recuerda-idea{font-size: 12px; margin-bottom: 4px; line-height: 1.3;}
.mz .recuerda-ejemplo{display: flex; flex-direction: column; align-items: center; gap: 3px;}
.mz .recuerda-ejemplo .titulo-tabla{font-size: 11.5px; font-weight: 700;}
.mz .recuerda-clave{font-size: 12px; text-align: center;}
.mz .tabla-de{border-collapse: collapse; font-size: 13px; margin: 0 auto;}
.mz .tabla-de th,.mz .tabla-de td{border: 1.5px solid var(--bosque); padding: 3px 14px; text-align: center; font-weight: 700;}
.mz .tabla-de th{background: #f3f3f3; font-size: 11.5px; font-family: sans-serif;}
.mz .tabla-de .celda-resaltada{background: #e3e3e3;}
.mz .tabla-de .celda-vacia{min-width: 52px;}
.mz .preg-grid{display: grid; grid-template-columns: 1fr 1fr; gap: 5px 18px; margin-top: 6px;}
.mz .preg-lista{display: flex; flex-direction: column; gap: 5px; margin-top: 6px;}
.mz .preg-fila{font-size: 12px; line-height: 1.35;}
.mz .preg-hueco{display: inline-block; min-width: 44px; border-bottom: 1.5px solid var(--bosque); height: 18px; vertical-align: middle; margin-left: 4px;}
.mz .preg-hueco-grande{display: inline-block; min-width: 95px; border-bottom: 1.5px solid var(--bosque); height: 18px; vertical-align: middle; margin-left: 4px;}
.mz .op-caja{display: inline-flex; align-items: center; gap: 6px; margin-left: 6px; vertical-align: middle;}
.mz .op-caja .hueco-op{display: inline-block; min-width: 75px; border-bottom: 1.5px solid var(--bosque); height: 18px;}
.mz .op-caja .igual{font-weight: 700; font-size: 13px;}
.mz .op-caja .hueco-res{display: inline-block; min-width: 44px; border: 1.5px solid var(--bosque); border-radius: 6px; height: 24px;}
.mz .vf-lista{display: flex; flex-direction: column; gap: 4px;}
.mz .vf-fila{display: grid; grid-template-columns: 1fr auto; gap: 10px; align-items: center; font-size: 12px; line-height: 1.3;}
.mz .vf-pills{display: flex; gap: 8px;}
.mz .vf-pill{width: 23px; height: 23px; border: 1.5px solid var(--bosque); border-radius: 50%; display: flex; align-items: center; justify-content: center; font-weight: 700; font-size: 12px; font-family: sans-serif;}
.mz .preg-fila,.mz .recuerda-idea{line-height: 1.725 !important;}
